def install_guards():
    op.execute(r"""
    CREATE FUNCTION talent_cycle_guard() RETURNS trigger LANGUAGE plpgsql AS $$
    DECLARE a talent_cycle_action; l talent_lock;
    BEGIN
      IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'talent_cycle_immutable'; END IF;
      IF TG_OP = 'INSERT' THEN
        IF NEW.state <> 'CONFIGURING' OR NEW.version <> 1 OR NEW.lock_number <> 0
          OR jsonb_typeof(NEW.assignments) <> 'array' OR jsonb_array_length(NEW.assignments) NOT BETWEEN 1 AND 500
          OR NOT EXISTS (SELECT 1 FROM snapshot s WHERE s.id=NEW.snapshot_id AND s.status='PUBLISHED' AND s.sha256=NEW.snapshot_sha256)
          OR NOT EXISTS (SELECT 1 FROM authz_policy_version p WHERE p.id=NEW.authz_policy_id AND p.sha256=NEW.authz_sha256)
          THEN RAISE EXCEPTION 'talent_cycle_initial_guard'; END IF;
        RETURN NEW;
      END IF;
      IF (to_jsonb(NEW) - ARRAY['state','version','lock_number']) IS DISTINCT FROM
         (to_jsonb(OLD) - ARRAY['state','version','lock_number']) OR NEW.version <> OLD.version+1
        THEN RAISE EXCEPTION 'talent_cycle_pin_guard'; END IF;
      SELECT * INTO a FROM talent_cycle_action WHERE cycle_id=OLD.id AND expected_version=OLD.version;
      IF a.id IS NULL OR a.actor_id <> OLD.owner_id THEN RAISE EXCEPTION 'talent_cycle_action_required'; END IF;
      IF a.action='LAUNCH' THEN
        IF OLD.state <> 'CONFIGURING' OR NEW.state <> 'ACTIVE' OR NEW.lock_number <> 0
          OR (SELECT count(*) FROM review_packet WHERE cycle_id=OLD.id) <> jsonb_array_length(OLD.assignments)
          OR EXISTS (SELECT 1 FROM review_packet WHERE cycle_id=OLD.id AND (state <> 'DRAFT' OR current_revision <> 1))
          THEN RAISE EXCEPTION 'talent_launch_guard'; END IF;
      ELSIF a.action='LOCK' THEN
        SELECT * INTO l FROM talent_lock WHERE cycle_id=OLD.id AND number=OLD.lock_number+1;
        IF OLD.state <> 'ACTIVE' OR NEW.state <> 'LOCKED' OR NEW.lock_number <> OLD.lock_number+1
          OR l.id IS NULL OR l.cycle_action_id <> a.id OR l.sha256 <> a.evidence_sha256
          OR EXISTS (SELECT 1 FROM review_packet WHERE cycle_id=OLD.id AND state <> 'LOCKED')
          THEN RAISE EXCEPTION 'talent_lock_guard'; END IF;
      ELSIF a.action='REOPEN' THEN
        IF OLD.state NOT IN ('ACTIVE','LOCKED') OR NEW.state <> 'ACTIVE' OR OLD.lock_number = 0
          OR NEW.lock_number <> OLD.lock_number THEN RAISE EXCEPTION 'talent_reopen_guard'; END IF;
      ELSE RAISE EXCEPTION 'talent_cycle_transition_guard'; END IF;
      RETURN NEW;
    END $$;

    CREATE FUNCTION talent_packet_guard() RETURNS trigger LANGUAGE plpgsql AS $$
    DECLARE c talent_cycle; a talent_decision; r packet_revision; s employee_version; target text;
    BEGIN
      IF TG_OP='DELETE' THEN RAISE EXCEPTION 'talent_packet_immutable'; END IF;
      SELECT * INTO c FROM talent_cycle WHERE id=NEW.cycle_id;
      IF TG_OP='INSERT' THEN
        SELECT * INTO s FROM employee_version WHERE id=NEW.source_version_id;
        IF c.state <> 'CONFIGURING' OR NEW.state <> 'BUILDING' OR NEW.version <> 0 OR NEW.current_revision <> 0
          OR s.snapshot_id <> c.snapshot_id OR s.employee_id <> NEW.employee_id OR s.status <> 'ACTIVE'
          OR s.valid_from > c.as_of OR (s.valid_to IS NOT NULL AND s.valid_to <= c.as_of)
          OR NEW.context->>'source_version_id' <> s.id OR NEW.context->>'employee_id' <> s.employee_id
          OR NEW.context->>'org_id' <> s.org_id OR NEW.context->>'snapshot_id' <> c.snapshot_id
          OR NOT EXISTS (SELECT 1 FROM jsonb_array_elements(c.assignments) x WHERE x->>'employee_id'=NEW.employee_id
            AND x->>'author_id'=NEW.author_id AND x->>'calibrator_id'=NEW.calibrator_id AND x->>'hr_signer_id'=NEW.hr_signer_id)
          THEN RAISE EXCEPTION 'talent_packet_initial_guard'; END IF;
        RETURN NEW;
      END IF;
      IF (to_jsonb(NEW)-ARRAY['state','version','current_revision']) IS DISTINCT FROM
         (to_jsonb(OLD)-ARRAY['state','version','current_revision']) OR NEW.version <> OLD.version+1
        THEN RAISE EXCEPTION 'talent_packet_pin_guard'; END IF;
      SELECT * INTO a FROM talent_decision WHERE packet_id=OLD.id AND expected_version=OLD.version;
      SELECT * INTO r FROM packet_revision WHERE packet_id=OLD.id AND number=NEW.current_revision;
      IF a.id IS NULL OR r.id IS NULL OR a.revision_id <> r.id THEN RAISE EXCEPTION 'talent_packet_action_required'; END IF;
      target := CASE a.action WHEN 'INITIAL' THEN 'DRAFT' WHEN 'EDIT' THEN 'DRAFT' WHEN 'SUBMIT' THEN 'SUBMITTED'
        WHEN 'START_CALIBRATION' THEN 'CALIBRATING' WHEN 'CALIBRATE' THEN 'CALIBRATING'
        WHEN 'ACK_CALIBRATION' THEN 'CALIBRATED' WHEN 'APPROVE' THEN 'APPROVED' WHEN 'RETURN' THEN 'RETURNED'
        WHEN 'LOCK' THEN 'LOCKED' WHEN 'REOPEN' THEN 'DRAFT' WHEN 'COMMENT' THEN OLD.state END;
      IF NEW.state <> target OR NEW.current_revision <> OLD.current_revision +
        (CASE WHEN a.action IN ('INITIAL','EDIT','CALIBRATE','REOPEN') THEN 1 ELSE 0 END)
        THEN RAISE EXCEPTION 'talent_packet_transition_guard'; END IF;
      IF a.action='CALIBRATE' AND NOT EXISTS(SELECT 1 FROM calibration_event WHERE revision_id=r.id)
        THEN RAISE EXCEPTION 'talent_calibration_event_required'; END IF;
      IF a.action='COMMENT' AND NOT EXISTS(SELECT 1 FROM talent_comment WHERE decision_id=a.id)
        THEN RAISE EXCEPTION 'talent_comment_required'; END IF;
      IF a.action='LOCK' AND NOT EXISTS (SELECT 1 FROM talent_lock l, jsonb_array_elements(l.document->'packets') x
         WHERE l.cycle_id=c.id AND l.number=c.lock_number+1 AND x->>'packet_id'=OLD.id AND x->>'revision_id'=r.id)
        THEN RAISE EXCEPTION 'talent_lock_packet_binding'; END IF;
      RETURN NEW;
    END $$;

    CREATE FUNCTION talent_revision_guard() RETURNS trigger LANGUAGE plpgsql AS $$
    DECLARE p review_packet; c talent_cycle; parent packet_revision;
    BEGIN
      SELECT * INTO p FROM review_packet WHERE id=NEW.packet_id;
      SELECT * INTO c FROM talent_cycle WHERE id=p.cycle_id;
      IF NEW.number <> p.current_revision+1 OR length(btrim(NEW.reason)) < 3
        OR NEW.review - ARRAY['accomplishments','collaboration','development','evidence'] <> '{}'::jsonb
        OR jsonb_typeof(NEW.review->'accomplishments') IS DISTINCT FROM 'string'
        OR jsonb_typeof(NEW.review->'collaboration') IS DISTINCT FROM 'string'
        OR jsonb_typeof(NEW.review->'development') IS DISTINCT FROM 'string'
        OR jsonb_typeof(NEW.review->'evidence') IS DISTINCT FROM 'array'
        OR length(NEW.review->>'accomplishments') > 2000 OR length(NEW.review->>'collaboration') > 2000
        OR length(NEW.review->>'development') > 2000 OR jsonb_array_length(NEW.review->'evidence') > 10
        THEN RAISE EXCEPTION 'talent_revision_shape_guard'; END IF;
      IF EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.review->'evidence') x
        WHERE x->>'source_version_id' IS DISTINCT FROM p.source_version_id
        OR x->>'kind' IS DISTINCT FROM 'WORKFORCE_CONTEXT'
        OR length(btrim(x->>'observation')) NOT BETWEEN 10 AND 240
        OR x - ARRAY['kind','source_version_id','observation'] <> '{}'::jsonb)
        THEN RAISE EXCEPTION 'talent_evidence_context_guard'; END IF;
      IF NEW.kind='INITIAL' THEN
        IF p.state <> 'BUILDING' OR c.state <> 'CONFIGURING' OR NEW.number <> 1 OR NEW.parent_id IS NOT NULL
          OR NEW.parent_sha256 IS NOT NULL OR NEW.author_id <> c.owner_id
          OR NEW.review <> '{"accomplishments":"","collaboration":"","development":"","evidence":[]}'::jsonb
          THEN RAISE EXCEPTION 'talent_initial_revision_guard'; END IF;
      ELSE
        SELECT * INTO parent FROM packet_revision WHERE id=NEW.parent_id;
        IF parent.id IS NULL OR parent.packet_id <> p.id OR parent.number <> p.current_revision
          OR parent.sha256 <> NEW.parent_sha256 OR c.state <> 'ACTIVE'
          THEN RAISE EXCEPTION 'talent_revision_parent_guard'; END IF;
        IF NEW.kind='EDIT' AND (p.state NOT IN ('DRAFT','RETURNED') OR NEW.author_id <> p.author_id)
          THEN RAISE EXCEPTION 'talent_author_revision_guard'; END IF;
        IF NEW.kind='CALIBRATE' AND (p.state <> 'CALIBRATING' OR NEW.author_id <> p.calibrator_id OR NEW.review=parent.review)
          THEN RAISE EXCEPTION 'talent_calibration_revision_guard'; END IF;
        IF NEW.kind='REOPEN' AND (p.state <> 'LOCKED' OR NEW.author_id <> c.owner_id OR NEW.review <> parent.review
          OR NOT EXISTS (SELECT 1 FROM talent_cycle_action WHERE cycle_id=c.id AND action='REOPEN'
            AND expected_version=c.version-1 AND actor_id=NEW.author_id AND evidence_sha256=parent.sha256 AND reason=NEW.reason))
          THEN RAISE EXCEPTION 'talent_reopen_revision_guard'; END IF;
      END IF;
      RETURN NEW;
    END $$;

    CREATE FUNCTION talent_decision_guard() RETURNS trigger LANGUAGE plpgsql AS $$
    DECLARE p review_packet; c talent_cycle; r packet_revision;
    BEGIN
      SELECT * INTO p FROM review_packet WHERE id=NEW.packet_id;
      SELECT * INTO c FROM talent_cycle WHERE id=p.cycle_id;
      SELECT * INTO r FROM packet_revision WHERE id=NEW.revision_id;
      IF NEW.expected_version <> p.version OR r.packet_id <> p.id OR length(btrim(NEW.reason)) < 3
        OR NEW.authorization->>'principal_id' IS DISTINCT FROM NEW.actor_id
        OR NOT EXISTS(SELECT 1 FROM authz_policy_version a WHERE a.id=NEW.authorization->>'policy_id' AND a.sha256=NEW.authorization->>'policy_sha256')
        THEN RAISE EXCEPTION 'talent_decision_binding_guard'; END IF;
      IF NEW.action IN ('INITIAL','EDIT','CALIBRATE','REOPEN') THEN
        IF r.number <> p.current_revision+1 OR r.kind <> NEW.action OR r.author_id <> NEW.actor_id OR r.reason <> NEW.reason
          THEN RAISE EXCEPTION 'talent_revision_decision_guard'; END IF;
      ELSE
        IF c.state <> 'ACTIVE' OR r.number <> p.current_revision THEN RAISE EXCEPTION 'talent_current_decision_guard'; END IF;
        IF NEW.action='SUBMIT' THEN
          IF NEW.actor_id <> p.author_id OR p.state NOT IN ('DRAFT','RETURNED') OR r.kind <> 'EDIT'
            OR length(btrim(r.review->>'accomplishments')) < 10 OR length(btrim(r.review->>'collaboration')) < 10
            OR length(btrim(r.review->>'development')) < 10 OR jsonb_array_length(r.review->'evidence') < 1
            THEN RAISE EXCEPTION 'talent_submission_guard'; END IF;
        ELSIF NEW.action='START_CALIBRATION' THEN
          IF NEW.actor_id <> p.calibrator_id OR p.state <> 'SUBMITTED' THEN RAISE EXCEPTION 'talent_calibration_start_guard'; END IF;
        ELSIF NEW.action='ACK_CALIBRATION' THEN
          IF NEW.actor_id <> p.calibrator_id OR p.state <> 'CALIBRATING' OR NOT NEW.acknowledgement
            OR length(btrim(r.review->>'accomplishments')) < 10 OR length(btrim(r.review->>'collaboration')) < 10
            OR length(btrim(r.review->>'development')) < 10 OR jsonb_array_length(r.review->'evidence') < 1
            THEN RAISE EXCEPTION 'talent_calibration_ack_guard'; END IF;
        ELSIF NEW.action IN ('APPROVE','RETURN') THEN
          IF NEW.actor_id <> p.hr_signer_id OR p.state <> 'CALIBRATED'
            OR (NEW.action='APPROVE' AND NOT NEW.acknowledgement)
            OR NOT EXISTS (SELECT 1 FROM talent_decision WHERE packet_id=p.id AND revision_id=r.id AND action='ACK_CALIBRATION' AND acknowledgement)
            THEN RAISE EXCEPTION 'talent_hr_signature_guard'; END IF;
        ELSIF NEW.action='COMMENT' THEN
          IF p.state NOT IN ('DRAFT','RETURNED','CALIBRATING') OR NEW.actor_id NOT IN (p.author_id,p.calibrator_id,p.hr_signer_id)
            THEN RAISE EXCEPTION 'talent_comment_participant_guard'; END IF;
        ELSIF NEW.action='LOCK' THEN
          IF p.state <> 'APPROVED' OR NEW.actor_id <> c.owner_id
            OR NOT EXISTS(SELECT 1 FROM talent_decision WHERE packet_id=p.id AND revision_id=r.id AND action='APPROVE' AND acknowledgement)
            THEN RAISE EXCEPTION 'talent_packet_lock_guard'; END IF;
        ELSE RAISE EXCEPTION 'talent_decision_action_guard'; END IF;
      END IF;
      RETURN NEW;
    END $$;

    CREATE FUNCTION talent_evidence_guard() RETURNS trigger LANGUAGE plpgsql AS $$
    DECLARE r packet_revision; p packet_revision; a talent_decision; c talent_cycle_action; cy talent_cycle;
    BEGIN
      IF TG_TABLE_NAME='calibration_event' THEN
        SELECT * INTO r FROM packet_revision WHERE id=NEW.revision_id;
        SELECT * INTO p FROM packet_revision WHERE id=NEW.before_revision_id;
        IF r.kind <> 'CALIBRATE' OR r.parent_id <> p.id OR r.author_id <> NEW.actor_id OR r.reason <> NEW.reason
          OR r.sha256 <> NEW.after_sha256 OR p.sha256 <> NEW.before_sha256 OR p.packet_id <> r.packet_id
          THEN RAISE EXCEPTION 'talent_calibration_evidence_guard'; END IF;
      ELSIF TG_TABLE_NAME='talent_comment' THEN
        SELECT * INTO a FROM talent_decision WHERE id=NEW.decision_id;
        IF a.action <> 'COMMENT' OR a.packet_id <> NEW.packet_id OR a.revision_id <> NEW.revision_id
          OR a.actor_id <> NEW.author_id OR length(btrim(NEW.body)) < 3
          THEN RAISE EXCEPTION 'talent_comment_evidence_guard'; END IF;
      ELSIF TG_TABLE_NAME='talent_lock' THEN
        SELECT * INTO cy FROM talent_cycle WHERE id=NEW.cycle_id;
        SELECT * INTO c FROM talent_cycle_action WHERE id=NEW.cycle_action_id;
        IF cy.state <> 'ACTIVE' OR NEW.number <> cy.lock_number+1 OR c.action <> 'LOCK' OR c.cycle_id <> cy.id
          OR c.expected_version <> cy.version OR c.evidence_sha256 <> NEW.sha256
          OR (NEW.document->>'row_count')::int <> jsonb_array_length(cy.assignments)
          OR jsonb_array_length(NEW.document->'packets') <> jsonb_array_length(cy.assignments)
          OR NEW.document->>'inputs_sha256' <> cy.inputs_sha256
          OR EXISTS(SELECT 1 FROM review_packet WHERE cycle_id=cy.id AND state NOT IN ('APPROVED','LOCKED'))
          THEN RAISE EXCEPTION 'talent_lock_evidence_guard'; END IF;
        IF EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.document->'packets') x
          LEFT JOIN review_packet pk ON pk.id=x->>'packet_id' AND pk.cycle_id=cy.id
          LEFT JOIN packet_revision rev ON rev.id=x->>'revision_id' AND rev.packet_id=pk.id
          WHERE pk.id IS NULL OR rev.id IS NULL OR rev.number <> pk.current_revision OR rev.sha256 <> x->>'sha256')
          THEN RAISE EXCEPTION 'talent_lock_revision_guard'; END IF;
      ELSIF TG_TABLE_NAME='talent_export' THEN
        IF NOT EXISTS(SELECT 1 FROM talent_lock l WHERE l.id=NEW.lock_id AND (l.document->>'row_count')::int=NEW.row_count)
          THEN RAISE EXCEPTION 'talent_export_count_guard'; END IF;
      END IF;
      RETURN NEW;
    END $$;
    CREATE TRIGGER talent_cycle_states BEFORE INSERT OR UPDATE OR DELETE ON talent_cycle FOR EACH ROW EXECUTE FUNCTION talent_cycle_guard();
    CREATE TRIGGER talent_packet_states BEFORE INSERT OR UPDATE OR DELETE ON review_packet FOR EACH ROW EXECUTE FUNCTION talent_packet_guard();
    CREATE TRIGGER talent_revision_insert BEFORE INSERT ON packet_revision FOR EACH ROW EXECUTE FUNCTION talent_revision_guard();
    CREATE TRIGGER talent_decision_insert BEFORE INSERT ON talent_decision FOR EACH ROW EXECUTE FUNCTION talent_decision_guard();
    """)
    for table in (
        "talent_policy_version",
        "talent_cycle_action",
        "packet_revision",
        "talent_decision",
        "calibration_event",
        "talent_comment",
        "talent_lock",
        "talent_export",
    ):
        op.execute(
            f"CREATE TRIGGER {table}_immutable BEFORE UPDATE OR DELETE ON {table} FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();"
        )
    for table in ("calibration_event", "talent_comment", "talent_lock", "talent_export"):
        op.execute(
            f"CREATE TRIGGER {table}_evidence BEFORE INSERT ON {table} FOR EACH ROW EXECUTE FUNCTION talent_evidence_guard();"
        )


def remove_guards():
    for name in (
        "talent_cycle_guard",
        "talent_packet_guard",
        "talent_revision_guard",
        "talent_decision_guard",
        "talent_evidence_guard",
    ):
        op.execute(f"DROP FUNCTION {name}() CASCADE")
